{# HTML entities to characters: numeric first, then the usual named ones. #}
{% macro unesc_num(c) %}list_reduce(regexp_extract_all({{ c }}, '&#(\d+);', 1), lambda a, x: replace(a, '&#' || x || ';', chr(try_cast(x as int))), {{ c }}){% endmacro %}
{% macro unesc_name(c) %}list_reduce(regexp_extract_all({{ c }}, '&([a-zA-Z]+);', 1), lambda a, x: replace(a, '&' || x || ';', coalesce(map {'nbsp': ' ', 'quot': '"', 'apos': '''', 'lt': '<', 'gt': '>', 'eacute': 'é', 'egrave': 'è', 'ecirc': 'ê', 'euml': 'ë', 'agrave': 'à', 'acirc': 'â', 'auml': 'ä', 'ccedil': 'ç', 'icirc': 'î', 'iuml': 'ï', 'ocirc': 'ô', 'ouml': 'ö', 'oelig': 'œ', 'ugrave': 'ù', 'ucirc': 'û', 'uuml': 'ü', 'szlig': 'ß', 'Eacute': 'É', 'Egrave': 'È', 'Agrave': 'À', 'Ccedil': 'Ç', 'laquo': '«', 'raquo': '»', 'rsquo': '’', 'lsquo': '‘', 'ndash': '–', 'mdash': '—', 'hellip': '…', 'euro': '€', 'amp': '&'}[x][1], '&' || x || ';')), {{ c }}){% endmacro %}
